package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.collaboration.submission.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class SubmissionStoreIntegrationTest {
 AssignmentStoreIntegrationTest parent;GroupStoreIntegrationTest f;SubmissionStore store;UUID group,space,study,assignment,author;
 @BeforeEach void setup(){parent=new AssignmentStoreIntegrationTest();parent.setup();f=parent.f;group=parent.group;space=parent.space;study=parent.study;assignment=parent.create(f.key()).assignment().assignmentId();author=f.ids.next();store=new SubmissionStore(f.source,parent.store,Clock.systemUTC());}
 void open(){parent.store.state(group,space,study,assignment,f.owner,1,"OPEN",f.trace);}
 SubmissionStore.Result submit(String key,long base,long assignmentVersion,String text){return store.submit(group,space,study,assignment,author,base,assignmentVersion,key,text,f.trace);}
 void status(int code,org.junit.jupiter.api.function.Executable op){parent.status(code,op);}
 int events(UUID id){return parent.events(id);}
 @Test void currentImmutableAttemptAndProtobufCommitTogether()throws Exception{
  assertNull(store.mine(group,space,study,assignment,author,true).submission());assertFalse(store.mine(group,space,study,assignment,author,true).canSubmit());open();assertTrue(store.mine(group,space,study,assignment,author,true).canSubmit());var v=submit(f.key(),0,2,"Answer <script>\n첫 답안").submission();assertEquals(7,v.submissionId().version());assertEquals(author,v.authorId());assertEquals("AUTHOR_AND_OWNER",v.audience());assertEquals(v,store.get(group,space,study,assignment,v.submissionId(),author,false));var h=store.history(group,space,study,assignment,v.submissionId(),author,false,Long.MAX_VALUE,5);assertEquals(v,h.items().getFirst().snapshot());assertEquals(author,h.items().getFirst().actorId());
  var e=SubmissionEnvelopeV1.parseFrom(f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.submissionId()));var p=SubmissionSnapshotV1.parseFrom(e.getPayload());assertEquals("AssignmentSubmitted",e.getEventType());assertEquals("Submission",e.getAggregateType());assertEquals(v.submissionId().toString(),e.getAggregateId());assertEquals(author.toString(),e.getActorId());assertEquals(f.trace,e.getTraceId());assertEquals(space.toString(),e.getSpaceId());assertEquals(study.toString(),p.getStudyId());assertEquals(assignment.toString(),p.getAssignmentId());assertEquals(2,p.getAssignmentVersion());assertEquals(v.content(),p.getContent());assertEquals("AUTHOR_AND_OWNER",p.getAudience());
 }
 @Test void resubmissionsPreserveOriginalAnswersAndExactRetryAfterCloseArchiveAndRestart(){
  open();String key=f.key();var a=submit(key,0,2,"First").submission();parent.store.metadata(group,space,study,assignment,f.owner,2,"Revised instructions","More detail",f.trace);var b=submit(f.key(),1,3,"Second").submission();assertEquals(a.submissionId(),b.submissionId());assertEquals(a.createdAt(),b.createdAt());assertEquals(2,b.version());assertEquals(3,b.assignmentVersion());var h=store.history(group,space,study,assignment,b.submissionId(),author,false,Long.MAX_VALUE,1);assertEquals(b,h.items().getFirst().snapshot());assertEquals(2L,h.nextBefore());assertEquals(a,store.history(group,space,study,assignment,b.submissionId(),author,false,2,1).items().getFirst().snapshot());
  parent.store.state(group,space,study,assignment,f.owner,3,"CLOSED",f.trace);parent.parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);var retry=new SubmissionStore(f.source,parent.store,Clock.systemUTC()).submit(group,space,study,assignment,author,0,2,key,"First",f.trace);assertFalse(retry.applied());assertEquals(a,retry.submission());assertEquals(b,store.mine(group,space,study,assignment,author,true).submission());assertEquals(2,events(b.submissionId()));status(409,()->submit(key,0,2,"Changed"));status(409,()->submit(key,2,2,"First"));status(409,()->submit(key,0,3,"First"));
 }
 @Test void staleOwnVersionAndChangedInstructionsCannotOverwrite(){
  open();var a=submit(f.key(),0,2,"First").submission();status(412,()->submit(f.key(),0,2,"Lost"));parent.store.metadata(group,space,study,assignment,f.owner,2,"Changed","",f.trace);status(412,()->submit(f.key(),1,2,"Outdated instructions"));assertEquals(a,store.mine(group,space,study,assignment,author,true).submission());assertEquals(1,events(a.submissionId()));
 }
 @Test void onlyOpenAssignmentsAcceptAndParentArchiveFreezesButKeepsHistory(){
  status(409,()->submit(f.key(),0,1,"Draft"));open();var a=submit(f.key(),0,2,"First").submission();parent.store.state(group,space,study,assignment,f.owner,2,"CLOSED",f.trace);status(409,()->submit(f.key(),1,3,"Closed"));parent.store.state(group,space,study,assignment,f.owner,3,"RETIRED",f.trace);status(409,()->submit(f.key(),1,4,"Retired"));assertFalse(store.mine(group,space,study,assignment,author,true).canSubmit());assertEquals(a,store.get(group,space,study,assignment,a.submissionId(),f.owner,true));assertEquals(1,store.history(group,space,study,assignment,a.submissionId(),f.owner,true,Long.MAX_VALUE,5).items().size());
 }
 @Test void authorAndOwnerReadRulesAndExactParentScopingHold(){
  open();var a=submit(f.key(),0,2,"Private answer").submission();UUID other=f.ids.next();assertNull(store.mine(group,space,study,assignment,other,true).submission());status(404,()->store.get(group,space,study,assignment,a.submissionId(),other,false));status(404,()->store.history(group,space,study,assignment,a.submissionId(),other,false,Long.MAX_VALUE,5));assertEquals(a,store.get(group,space,study,assignment,a.submissionId(),f.owner,true));status(404,()->store.get(group,space,study,f.owner,a.submissionId(),author,false));status(404,()->store.get(group,space,f.owner,assignment,a.submissionId(),author,false));status(404,()->store.get(group,f.owner,study,assignment,a.submissionId(),author,false));status(404,()->store.get(f.owner,space,study,assignment,a.submissionId(),author,false));status(404,()->store.submit(group,space,f.owner,assignment,author,0,2,f.key(),"Wrong study",f.trace));assertFalse(store.mine(group,space,study,assignment,author,false).canSubmit());
 }
 @Test void archivedStudyFreezesOpenAssignmentButExactRetryAndOwnHistorySurvive(){
  open();String key=f.key();var a=submit(key,0,2,"Before Study archive").submission();parent.parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);assertFalse(store.mine(group,space,study,assignment,author,true).canSubmit());status(409,()->submit(f.key(),1,2,"After Study archive"));assertEquals(a,submit(key,0,2,"Before Study archive").submission());assertEquals(1,events(a.submissionId()));assertEquals(1,store.history(group,space,study,assignment,a.submissionId(),author,false,Long.MAX_VALUE,5).items().size());
 }
 @Test void ownerCatalogIsBoundedMetadataAndSubmissionDoesNotAdvanceAssignment(){
  open();for(int n=0;n<3;n++)store.submit(group,space,study,assignment,f.ids.next(),0,2,f.key(),"Answer "+n,f.trace);var page=store.list(group,space,study,assignment,null,2);assertEquals(2,page.items().size());assertNotNull(page.nextAfter());assertEquals(1,store.list(group,space,study,assignment,page.nextAfter(),2).items().size());assertEquals(2,parent.store.get(group,space,study,assignment).version());assertEquals(1,parent.parent.store.get(group,space,study).version());
 }
 @Test void simultaneousRetriesAndResubmissionsHaveOneWinner()throws Exception{
  open();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);String key=f.key();var a=pool.submit(()->{barrier.await();return submit(key,0,2,"First");});var b=pool.submit(()->{barrier.await();return submit(key,0,2,"First");});var x=a.get();var y=b.get();assertNotEquals(x.applied(),y.applied());assertEquals(x.submission(),y.submission());assertEquals(1,events(x.submission().submissionId()));var results=new ArrayList<Future<Boolean>>();for(String text:List.of("A","B"))results.add(pool.submit(()->{barrier.await();try{submit(f.key(),1,2,text);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(results.get(0).get(),results.get(1).get());assertEquals(2,events(x.submission().submissionId()));}
 }
 @Test void closeAndSubmitUseSameAssignmentLock()throws Exception{
  open();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return parent.store.state(group,space,study,assignment,f.owner,2,"CLOSED",f.trace);});var b=pool.submit(()->{barrier.await();try{return submit(f.key(),0,2,"Racing answer").submission();}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals("CLOSED",a.get().state());var v=b.get();assertEquals(v,store.mine(group,space,study,assignment,author,true).submission());status(409,()->submit(f.key(),v==null?0:1,3,"After close"));}
 }
 @Test void outboxFailureRollsBackNewAndExistingAnswerAndAttempt(){
  open();String name="submission_fail_"+assignment.toString().replace("-","");String check=" CHECK (aggregatetype <> 'submission' OR trace_id <> '"+f.trace+"') NOT VALID";f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->submit(f.key(),0,2,"Fail"));assertNull(store.mine(group,space,study,assignment,author,true).submission());assertTrue(store.list(group,space,study,assignment,null,20).items().isEmpty());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var a=submit(f.key(),0,2,"First").submission();f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->submit(f.key(),1,2,"Fail retry"));assertEquals(a,store.mine(group,space,study,assignment,author,true).submission());assertEquals(1,events(a.submissionId()));assertEquals(1,store.history(group,space,study,assignment,a.submissionId(),author,false,Long.MAX_VALUE,5).items().size());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}
 }
}
